import request from 'supertest';
import { describe, expect, it } from 'vitest';
import { createApp } from '../src/app.ts';

describe('users api', () => {
  it('creates, lists, gets, updates, deletes, and enforces idempotency and uniqueness', async () => {
    const app = createApp();

    const create1 = await request(app)
      .post('/v1/users')
      .set('Idempotency-Key', 'key-1')
      .send({ email: 'a@example.com', name: 'Alice' })
      .expect(201);

    expect(create1.headers.location).toBe(`/v1/users/${create1.body.id}`);
    expect(create1.body).toMatchObject({ email: 'a@example.com', name: 'Alice', role: 'member' });

    const replay = await request(app)
      .post('/v1/users')
      .set('Idempotency-Key', 'key-1')
      .send({ email: 'a@example.com', name: 'Alice' })
      .expect(201);

    expect(replay.headers['idempotent-replayed']).toBe('true');
    expect(replay.body).toEqual(create1.body);

    await request(app)
      .post('/v1/users')
      .set('Idempotency-Key', 'key-1')
      .send({ email: 'b@example.com', name: 'Bob' })
      .expect(422);

    const create2 = await request(app)
      .post('/v1/users')
      .send({ email: 'b@example.com', name: 'Bob', role: 'admin' })
      .expect(201);

    const conflict = await request(app)
      .post('/v1/users')
      .send({ email: 'a@example.com', name: 'Another' })
      .expect(409);
    expect(conflict.headers['content-type']).toContain('application/problem+json');

    const list = await request(app).get('/v1/users').expect(200);
    expect(list.body.data).toHaveLength(2);
    expect(list.body.nextCursor).toBeNull();

    const first = await request(app).get(`/v1/users/${create1.body.id}`).expect(200);
    expect(first.body).toMatchObject(create1.body);

    const patchConflict = await request(app)
      .patch(`/v1/users/${create2.body.id}`)
      .send({ email: 'a@example.com' })
      .expect(409);
    expect(patchConflict.headers['content-type']).toContain('application/problem+json');

    const patched = await request(app)
      .patch(`/v1/users/${create2.body.id}`)
      .send({ name: 'Bobby' })
      .expect(200);
    expect(patched.body).toMatchObject({ ...create2.body, name: 'Bobby' });

    await request(app).delete(`/v1/users/${create1.body.id}`).expect(204);
    await request(app).get(`/v1/users/${create1.body.id}`).expect(404);
  });

  it('paginates with cursor and validates requests', async () => {
    const app = createApp();
    const ids: string[] = [];
    for (let i = 0; i < 3; i += 1) {
      const res = await request(app).post('/v1/users').send({ email: `u${i}@example.com`, name: `U${i}` }).expect(201);
      ids.push(res.body.id);
    }

    const page1 = await request(app).get('/v1/users?limit=2').expect(200);
    expect(page1.body.data).toHaveLength(2);
    expect(page1.body.nextCursor).toEqual(expect.any(String));

    const page2 = await request(app).get(`/v1/users?limit=2&cursor=${page1.body.nextCursor}`).expect(200);
    expect(page2.body.data).toHaveLength(1);

    await request(app).get('/v1/users?limit=0').expect(422);
    await request(app).get('/v1/users?cursor=bad').expect(422);
    await request(app).get('/v1/users/not-a-uuid').expect(422);
    await request(app).post('/v1/users').send({ email: 'x@example.com' }).expect(422);
    await request(app).patch(`/v1/users/${ids[0]}`).send({}).expect(422);
    await request(app).patch(`/v1/users/${ids[0]}`).send('{').set('Content-Type', 'application/json').expect(400);
  });
});

import type { Router } from 'express';
import { createUsersRouter } from './users.ts';

export function registerRoutes(app: Router): void {
  app.use('/v1/users', createUsersRouter());
}

import { randomUUID } from 'node:crypto';
import { Router } from 'express';
import { z } from 'zod';
import { idempotency } from '../lib/idempotency.ts';
import { CursorQuerySchema, paginate, pageSchema } from '../lib/pagination.ts';
import { conflict, notFound, unprocessable } from '../lib/problem.ts';

const UserRoleSchema = z.enum(['admin', 'member']);
const UserSchema = z.object({
  id: z.string().uuid(),
  email: z.string().email(),
  name: z.string().min(1).max(100),
  role: UserRoleSchema,
  createdAt: z.string().datetime(),
  updatedAt: z.string().datetime(),
});
const UserListSchema = pageSchema(UserSchema);
const CreateUserSchema = z.object({ email: z.string().email(), name: z.string().min(1).max(100), role: UserRoleSchema.optional() });
const PatchUserSchema = CreateUserSchema.partial();
const UserIdSchema = z.object({ userId: z.string().uuid() });

export function createUsersRouter(): Router {
  const router = Router();
  const users = new Map<string, z.infer<typeof UserSchema>>();
  const idempotentKeys = new Map<string, { fingerprint: string; response: { status: number; headers: Record<string, string>; body: unknown } }>();
  router.use('/' , idempotency());
  router.get('/', (req, res, next) => {
    try {
      const query = CursorQuerySchema.parse(req.query);
      const items = [...users.values()].sort((a, b) => a.id.localeCompare(b.id));
      res.json(UserListSchema.parse(paginate(items, query, (u) => u.id)));
    } catch (err) { next(err); }
  });
  router.post('/', (req, res, next) => { try {
    const body = CreateUserSchema.parse(req.body);
    if ([...users.values()].some((u) => u.email === body.email)) throw conflict('A user with that email already exists.');
    const now = new Date().toISOString();
    const user = { id: randomUUID(), email: body.email, name: body.name, role: body.role ?? 'member', createdAt: now, updatedAt: now };
    users.set(user.id, user);
    res.location(`/v1/users/${user.id}`).status(201).json(UserSchema.parse(user));
  } catch (err) { next(err); } });
  router.get('/:userId', (req, res, next) => { try {
    const { userId } = UserIdSchema.parse(req.params);
    const user = users.get(userId);
    if (!user) throw notFound('User not found.');
    res.json(UserSchema.parse(user));
  } catch (err) { next(err); } });
