import { randomUUID } from 'node:crypto';
import type { Request, Response, Router } from 'express';
import { Router as createRouter } from 'express';
import { z } from 'zod';
import { idempotency } from '../lib/idempotency.ts';
import { pageSchema, paginate } from '../lib/pagination.ts';
import { conflict, notFound, unprocessable } from '../lib/problem.ts';

const UserRoleSchema = z.enum(['admin', 'member']);
const UserSchema = z.object({
  id: z.string().uuid(),
  email: z.string().email(),
  name: z.string().min(1).max(100),
  role: UserRoleSchema,
  createdAt: z.string().datetime(),
  updatedAt: z.string().datetime(),
});
const UserInputSchema = z.object({
  email: z.string().email(),
  name: z.string().min(1).max(100),
  role: UserRoleSchema.optional(),
});
const UserCreateSchema = UserInputSchema;
const UserPatchSchema = UserInputSchema.partial();
const UsersListQuerySchema = z.object({ limit: z.coerce.number().int().min(1).max(100).default(20), cursor: z.string().optional() });
const UsersPageSchema = pageSchema(UserSchema);

type User = z.infer<typeof UserSchema>;

type Store = { users: User[]; idempotency: Map<string, unknown> };

function nowIso() { return new Date().toISOString(); }
function createStore(): Store { return { users: [], idempotency: new Map() }; }
function byId(a: User, b: User): number { return a.id.localeCompare(b.id); }

export function createUsersRouter(): Router {
  const router = createRouter();
  const store = createStore();
  router.use(idempotency());
  router.get('/v1/users', (req: Request, res: Response) => {
    const query = UsersListQuerySchema.parse(req.query);
    const page = paginate(store.users.slice().sort(byId), query, (u) => u.id);
    res.json(UsersPageSchema.parse(page));
  });
  router.post('/v1/users', (req: Request, res: Response) => {
    const body = UserCreateSchema.parse(req.body);
    if (store.users.some((u) => u.email === body.email)) throw conflict('email already exists');
    const user: User = { id: randomUUID(), createdAt: nowIso(), updatedAt: nowIso(), role: body.role ?? 'member', email: body.email, name: body.name };
    store.users.push(user);
    res.location(`/v1/users/${user.id}`).status(201).json(UserSchema.parse(user));
  });
  router.get('/v1/users/:userId', (req, res) => {
    const user = store.users.find((u) => u.id === req.params.userId);
    if (!user) throw notFound(`user ${req.params.userId} not found`);
    res.json(UserSchema.parse(user));
  });
  router.patch('/v1/users/:userId', (req, res) => {
    const patch = UserPatchSchema.parse(req.body);
    if (Object.keys(patch).length === 0) throw unprocessable('patch body must not be empty');
    const user = store.users.find((u) => u.id === req.params.userId);
    if (!user) throw notFound(`user ${req.params.userId} not found`);
    if (patch.email && store.users.some((u) => u.id !== user.id && u.email === patch.email)) throw conflict('email already exists');
    Object.assign(user, patch, { updatedAt: nowIso() });
    res.json(UserSchema.parse(user));
  });
  router.delete('/v1/users/:userId', (req, res) => {
    const index = store.users.findIndex((u) => u.id === req.params.userId);
    if (index < 0) throw notFound(`user ${req.params.userId} not found`);
    store.users.splice(index, 1);
    res.status(204).end();
  });
  return router;
}

