import express from 'express';
import request from 'supertest';
import type { Response } from 'supertest';
import { afterEach, describe, expect, it, vi } from 'vitest';
import { z } from 'zod';
import { createApp } from '../../src/app.ts';
import { errorHandler, notFoundHandler } from '../../src/lib/errors.ts';
import { ProblemSchema, notFound } from '../../src/lib/problem.ts';

function expectProblem(res: Response, status: number, slug: string) {
  expect(res.status).toBe(status);
  expect(res.headers['content-type']).toMatch(/^application\/problem\+json/);
  const problem = ProblemSchema.parse(res.body);
  expect(problem.status).toBe(status);
  expect(problem.type).toBe(`https://api.sf/problems/${slug}`);
  return problem;
}

const ThingSchema = z.object({ name: z.string().min(1), size: z.number().int() });

/** A throwaway app with one validating route, wired like createApp(). */
function appWithRoute() {
  const app = express();
  app.use(express.json());
  app.post('/v1/things', (req, res) => {
    const body = ThingSchema.parse(req.body);
    res.status(201).json(ThingSchema.parse(body));
  });
  app.get('/v1/things/:thingId', (req) => {
    throw notFound(`thing ${String(req.params.thingId)} not found`);
  });
  app.get('/v1/boom', () => {
    throw new Error('secret internals');
  });
  app.use(notFoundHandler);
  app.use(errorHandler);
  return app;
}

describe('createApp error handling', () => {
  afterEach(() => {
    vi.restoreAllMocks();
  });

  it('answers unknown routes with a 404 problem', async () => {
    const res = await request(createApp()).get('/v1/does-not-exist?x=1');
    const problem = expectProblem(res, 404, 'not-found');
    expect(problem.instance).toBe('/v1/does-not-exist?x=1');
    expect(problem.detail).toContain('GET /v1/does-not-exist');
  });

  it('answers malformed JSON with a 400 problem', async () => {
    const res = await request(createApp()).post('/v1/anything').set('Content-Type', 'application/json').send('{"name":');
    expectProblem(res, 400, 'malformed-json');
  });

  it('maps a ZodError to a 422 problem listing each issue', async () => {
    const res = await request(appWithRoute()).post('/v1/things').send({ name: '', size: 1.5 });
    const problem = expectProblem(res, 422, 'validation');
    expect(problem.detail).toContain('name: ');
    expect(problem.detail).toContain('size: ');
    expect(problem.detail.split('; ')).toHaveLength(2);
  });

  it('passes valid bodies through', async () => {
    const res = await request(appWithRoute()).post('/v1/things').send({ name: 'a', size: 2 });
    expect(res.status).toBe(201);
    expect(res.body).toEqual({ name: 'a', size: 2 });
  });

  it('sends a thrown HttpProblem with its own status', async () => {
    const res = await request(appWithRoute()).get('/v1/things/42');
    const problem = expectProblem(res, 404, 'not-found');
    expect(problem.detail).toBe('thing 42 not found');
    expect(problem.instance).toBe('/v1/things/42');
  });

  it('hides unexpected errors behind a 500 problem without a stack', async () => {
    const stderr = vi.spyOn(process.stderr, 'write').mockImplementation(() => true);
    const res = await request(appWithRoute()).get('/v1/boom');
    const problem = expectProblem(res, 500, 'internal');
    expect(JSON.stringify(res.body)).not.toContain('secret internals');
    expect(problem.detail).not.toContain('at ');
    expect(stderr.mock.calls.map(([chunk]) => String(chunk)).join('')).toContain('secret internals');
  });

  it('does not leave createApp with a no-op router', async () => {
    const res = await request(createApp()).get('/v1/users');
    expect(res.status).not.toBe(404);
  });
});

import type { Router } from 'express';
import { createUsersRouter } from './users.ts';

export function registerRoutes(app: Router): void {
  app.use('/v1/users', createUsersRouter());
}

import { randomUUID } from 'node:crypto';
import { type Request, type Router } from 'express';
import { z } from 'zod';
import { badRequest, conflict, notFound, unprocessable } from '../lib/problem.ts';
import { CursorQuerySchema, encodeCursor, pageSchema, paginate } from '../lib/pagination.ts';
import { IdempotencyHeadersSchema } from '../lib/idempotency.ts';

const UserRoleSchema = z.enum(['admin', 'member']);
const UserIdSchema = z.string().uuid();
const UserSchema = z.object({
  id: UserIdSchema,
  email: z.string().email(),
  name: z.string().min(1).max(100),
  role: UserRoleSchema,
  createdAt: z.string().datetime(),
  updatedAt: z.string().datetime(),
});
const UserInputSchema = z.object({
  email: z.string().email(),
  name: z.string().min(1).max(100),
  role: UserRoleSchema.optional(),
});
const UserPatchSchema = UserInputSchema.partial();
const UsersListSchema = pageSchema(UserSchema);

type User = z.infer<typeof UserSchema>;

type IdempotentRecord = { fingerprint: string; status: number; headers: Record<string, string>; body?: unknown };

export function createUsersRouter(): Router {
  const router = Router();
  const users: User[] = [];
  const idempotencyStore = new Map<string, IdempotentRecord>();

  router.post('/', (req, res, next) => {
    const headerResult = IdempotencyHeadersSchema.safeParse(req.header('Idempotency-Key') ? { 'idempotency-key': req.header('Idempotency-Key') } : {});
    if (!headerResult.success) return next(unprocessable('detail'));
    const bodyResult = UserInputSchema.safeParse(req.body);
    if (!bodyResult.success) return next(unprocessable(bodyResult.error.issues.map((i) => i.path.join('.')).join(', ')));
    const fingerprint = JSON.stringify(bodyResult.data);
    const key = req.header('Idempotency-Key');
    if (key) {
      const record = idempotencyStore.get(key);
      if (record) {
        if (record.fingerprint !== fingerprint) return next(unprocessable('idempotency-key'));
        res.status(record.status).set(record.headers);
        return res.json(record.body);
      }
    }
    if (users.some((u) => u.email === bodyResult.data.email)) return next(conflict('email exists'));
    const now = new Date().toISOString();
    const user: User = { id: randomUUID(), email: bodyResult.data.email, name: bodyResult.data.name, role: bodyResult.data.role ?? 'member', createdAt: now, updatedAt: now };
    users.push(user);
    const headers = { Location: `/v1/users/${user.id}` };
    if (key) idempotencyStore.set(key, { fingerprint, status: 201, headers, body: user });
    return res.status(201).set(headers).json(user);
  });

  router.get('/', (req, res, next) => {
    const queryResult = CursorQuerySchema.safeParse(req.query);
    if (!queryResult.success) return next(unprocessable(queryResult.error.issues.map((i) => i.path.join('.')).join(', ')));
    return res.json(UsersListSchema.parse(paginate(users, queryResult.data, (u) => u.id)));
  });

  router.get('/:userId', (req, res, next) => {
    const idResult = UserIdSchema.safeParse(req.params.userId);
    if (!idResult.success) return next(unprocessable('userId'));
    const user = users.find((u) => u.id === idResult.data);
    if (!user) return next(notFound('user not found'));
    return res.json(UserSchema.parse(user));
  });

  router.patch('/:userId', (req, res, next) => {
    const idResult = UserIdSchema.safeParse(req.params.userId);
    if (!idResult.success) return next(unprocessable('userId'));
    const bodyResult = UserPatchSchema.safeParse(req.body);
    if (!bodyResult.success || Object.keys(bodyResult.data).length === 0) return next(unprocessable('body'));
    const user = users.find((u) => u.id === idResult.data);
    if (!user) return next(notFound('user not found'));
    if (bodyResult.data.email && users.some((u) => u.email === bodyResult.data.email && u.id !== user.id)) return next(conflict('email exists'));
    Object.assign(user, bodyResult.data, { updatedAt: new Date().toISOString() });
    return res.json(UserSchema.parse(user));
  });

  router.delete('/:userId', (req, res, next) => {
    const idResult = UserIdSchema.safeParse(req.params.userId);
    if (!idResult.success) return next(unprocessable('userId'));
    const index = users.findIndex((u) => u.id === idResult.data);
    if (index < 0) return next(notFound('user not found'));
    users.splice(index, 1);
    return res.status(204).send();
  });

  return router;
}

