import { randomUUID } from 'node:crypto';
import { Router } from 'express';
import { z } from 'zod';
import { idempotency } from '../lib/idempotency.ts';
import { paginate, pageSchema, CursorQuerySchema } from '../lib/pagination.ts';
import { conflict, notFound, unprocessable } from '../lib/problem.ts';

const UserRoleSchema = z.enum(['admin', 'member']);
const UserSchema = z.object({
  id: z.string().uuid(),
  email: z.string().email(),
  name: z.string().min(1).max(100),
  role: UserRoleSchema,
  createdAt: z.string().datetime(),
  updatedAt: z.string().datetime(),
});

const UserListQuerySchema = CursorQuerySchema.extend({ limit: z.coerce.number().int().min(1).max(100).default(20) });
const CreateUserBodySchema = z.object({ email: z.string().email(), name: z.string().min(1).max(100), role: UserRoleSchema.optional() });
const UpdateUserBodySchema = z.object({ email: z.string().email().optional(), name: z.string().min(1).max(100).optional(), role: UserRoleSchema.optional() }).refine((v) => Object.keys(v).length > 0, 'empty patch');
const UserParamsSchema = z.object({ userId: z.string().uuid() });

export type User = z.infer<typeof UserSchema>;

export function createUsersRouter(): Router {
  const router = Router();
  const users = new Map<string, User>();
  router.use(idempotency());

  router.get('/', (req, res) => {
    const query = UserListQuerySchema.parse(req.query);
    const items = [...users.values()].sort((a, b) => a.id.localeCompare(b.id));
    res.json(pageSchema(UserSchema).parse(paginate(items, query, (user) => user.id)));
  });

  router.post('/', (req, res) => {
    const body = CreateUserBodySchema.parse(req.body);
    if ([...users.values()].some((user) => user.email === body.email)) throw conflict('Email already exists.');
    const now = new Date().toISOString();
    const user: User = { id: randomUUID(), email: body.email, name: body.name, role: body.role ?? 'member', createdAt: now, updatedAt: now };
    users.set(user.id, user);
    res.setHeader('Location', `/v1/users/${user.id}`).status(201).json(UserSchema.parse(user));
  });

  router.get('/:userId', (req, res) => {
    const { userId } = UserParamsSchema.parse(req.params);
    const user = getUser(users, userId);
    res.json(UserSchema.parse(user));
  });

  router.patch('/:userId', (req, res) => {
    const { userId } = UserParamsSchema.parse(req.params);
    const user = getUser(users, userId);
    const patch = UpdateUserBodySchema.parse(req.body);
    if (patch.email && [...users.values()].some((existing) => existing.id !== user.id && existing.email === patch.email)) throw conflict('Email already exists.');
    const updated: User = { ...user, ...patch, updatedAt: new Date().toISOString() };
    users.set(updated.id, updated);
    res.json(UserSchema.parse(updated));
  });

  router.delete('/:userId', (req, res) => {
    const { userId } = UserParamsSchema.parse(req.params);
    const user = getUser(users, userId);
    users.delete(user.id);
    res.status(204).end();
  });

  return router;
}

function getUser(users: Map<string, User>, userId: string): User {
  const parsed = z.string().uuid().safeParse(userId);
  if (!parsed.success) throw unprocessable('Invalid path parameter.');
  const user = users.get(userId);
  if (!user) throw notFound('User not found.');
  return user;
}
